import{_ as r,o as a,c as e,a5 as d}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"作品简报与交付卡","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/artifact-brief.zh.md","filePath":"public/downloads/worksheets/artifact-brief.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/artifact-brief.zh.md"};function i(o,t,b,l,n,s){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="作品简报与交付卡" tabindex="-1">作品简报与交付卡 <a class="header-anchor" href="#作品简报与交付卡" aria-label="Permalink to &quot;作品简报与交付卡&quot;">​</a></h1><p>作品不必从一开始就完整，但必须从一开始就有边界。复制这张卡到私有项目目录，保留独立版、修订版、反馈版和交付版。不要写入密码、客户资料、未获授权的第三方信息或不必要的隐私。</p><h2 id="_1-作品边界" tabindex="-1">1. 作品边界 <a class="header-anchor" href="#_1-作品边界" aria-label="Permalink to &quot;1. 作品边界&quot;">​</a></h2><h3 id="artifact-brief-—-yyyy-mm-dd" tabindex="-1">Artifact Brief — YYYY-MM-DD <a class="header-anchor" href="#artifact-brief-—-yyyy-mm-dd" aria-label="Permalink to &quot;Artifact Brief — YYYY-MM-DD&quot;">​</a></h3><p>作品名称：<br> 真实场景：<br> 受众/使用者：<br> 要解决的一个问题：</p><p>输入材料与来源：<br> 我当前的基线：<br> 关键假设：</p><p>最小交付物：<br> 格式、时间与其他限制：<br> 完成标准：<br> 明确不做什么：</p><p>第一版截止时间：<br> 谁会提供反馈：<br> 需要保留的证据：<br> 失败时如何缩小、暂停或回滚：<br> 下一次复查日期：</p><h2 id="_2-四个版本" tabindex="-1">2. 四个版本 <a class="header-anchor" href="#_2-四个版本" aria-label="Permalink to &quot;2. 四个版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>完成条件</th><th>保留什么</th></tr></thead><tbody><tr><td>独立版</td><td>不看答案、不让 AI 代写，完成最小动作</td><td>原始文件、用时、卡点</td></tr><tr><td>结构版</td><td>受众能找到问题、结论和下一步</td><td>结构差异、事实与推测标记</td></tr><tr><td>反馈版</td><td>真实读者、用户、同伴或明确角色的 AI 完成审阅</td><td>反馈、错误分类、采纳/拒绝理由</td></tr><tr><td>交付版</td><td>他人不依赖你的口头补充也能开始使用</td><td>版本、限制、来源、已知问题、交接记录</td></tr></tbody></table><h2 id="_3-质量门" tabindex="-1">3. 质量门 <a class="header-anchor" href="#_3-质量门" aria-label="Permalink to &quot;3. 质量门&quot;">​</a></h2><table tabindex="0"><thead><tr><th>门</th><th>检查问题</th><th>证据位置</th><th>负责人/日期</th></tr></thead><tbody><tr><td>清楚</td><td>受众知道问题和下一步吗？</td><td></td><td></td></tr><tr><td>准确</td><td>事实、引用、代码和数字能回到来源或测试吗？</td><td></td><td></td></tr><tr><td>可用</td><td>主要动作在真实限制下能完成吗？</td><td></td><td></td></tr><tr><td>可维护</td><td>版本、依赖、限制和接手人清楚吗？</td><td></td><td></td></tr><tr><td>可负责</td><td>隐私、版权、权限和错误后果已处理吗？</td><td></td><td></td></tr></tbody></table><p>没有证据的“通过”先写成“待核验”。速度、字数和功能数量只是代理指标，不能替代质量门。</p><h2 id="_4-ai-与反馈记录" tabindex="-1">4. AI 与反馈记录 <a class="header-anchor" href="#_4-ai-与反馈记录" aria-label="Permalink to &quot;4. AI 与反馈记录&quot;">​</a></h2><p>AI/工具与日期：<br> 允许它做的工作：<br> 我保留的人类判断：<br> 它指出的三个最高影响问题：<br> 我采纳/拒绝了什么，为什么：<br> 真实读者/用户复述的主旨：<br> 最需要修正的一处：</p><p>先保存自己的版本，再让 AI 诊断、模拟受众或生成平行任务。关键事实、权限、隐私、成本和最终署名由人确认。</p><h2 id="_5-交付与回滚" tabindex="-1">5. 交付与回滚 <a class="header-anchor" href="#_5-交付与回滚" aria-label="Permalink to &quot;5. 交付与回滚&quot;">​</a></h2><p>交付对象与授权范围：<br> 交付日期与版本：<br> 使用说明：<br> 已知限制：<br> 支持与联系人：<br> 成本与留存期限：<br> 暂停/降级/回滚触发条件：<br> 发现问题后的通知对象：<br> 下一次复查日期：</p><p>交付不是终点。至少在 3–7 天后用相近条件复测一次，记录别人是否能独立开始、哪里需要解释，以及下一版本只改变什么。</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-3/4-artifacts-and-delivery" target="_blank" rel="noreferrer">作品篇：把学会变成做出</a> ｜ <a href="https://byoungd.github.io/up/templates/90-day-cycle" target="_blank" rel="noreferrer">九十日行动总表</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/artifact-brief" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-08-31。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',22)])])}const f=r(h,[["render",i]]);export{c as __pageData,f as default};
